    const EquipmentClass *FindEquipmentClass(std::string_view guid) {
        const auto found = std::lower_bound(g_EquipmentClasses.begin(), g_EquipmentClasses.end(), guid, [](const EquipmentClass &entry, std::string_view value) {
            return entry.guid < value;
        });
        return found != g_EquipmentClasses.end() && found->guid == guid ? &*found : nullptr;
    }
